//! Preserve the existing similarity frequency/unit behavior, conversion order,
//! and complete Wasm validity. This does not assert normative PHP recursive scoring.
use vybe_runtime::{Chunk,Value,VM};
fn compile(s:&str)->Vec<Chunk>{static INIT:std::sync::Once=std::sync::Once::new();INIT.call_once(vybe_language_php::register);let ast=vybe_language_php::parse(&format!("<?php {s}")).unwrap();let p=vybe_compiler::profile::parse_profile(vybe_language_php::profile_source()).unwrap();vybe_compiler::Compiler::with_profile(p).compile(&ast).unwrap()}
fn run(s:&str)->Value{let c=compile(s);let b=vybe_platform_wasm::write_wasm(&c);if let Err(e)=wasmparser::Validator::new_with_features(wasmparser::WasmFeatures::all()).validate_all(&b){std::fs::write(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("source-full-native-failure.wasm"),b).unwrap();panic!("complete Source unwaived:{e}");}let mut vm=VM::new();vybe_compiler::primitives::platforms::register_platforms_all(&mut vm);vm.run(c).unwrap()}
#[test]fn actual_legacy_literals_empty_scalar_unicode_and_threshold(){for(s,n)in [("return similar_text('ab','ba');",2.),("return similar_text('a','aaa');",3.),("return similar_text('','abc');",0.),("return similar_text('abc','');",0.),("return similar_text(123,124);",2.),("return similar_text(true,null);",0.),("return similar_text('😀','🦀');",2.)]{assert_eq!(run(s),Value::F64(n),"legacy contract {s}; not normativePHP");}for(a,b)in [("a".repeat(63),"a".repeat(65)),("a".repeat(64),"a".repeat(64)),("é".repeat(65),"é".repeat(64)),("é".repeat(128),"€".repeat(128))]{assert_eq!(run(&format!("return similar_text('{a}','{b}');")),Value::F64(if a.starts_with('é')&&b.starts_with('€'){0.}else{b.encode_utf16().count()as f64}));}}
#[test]fn actual_argument_and_conversion_trace_and_primitive_method_override(){let s=r#"$trace='';class SimilarInput{public $name;public $text;function __construct($n,$s){$this->name=$n;$this->text=$s;}function __toString(){global $trace;$trace.=$this->name;return $this->text;}function charAt($i){global $trace;$trace.='BAD';return 'x';}}function left(){global $trace;$trace.='l';return new SimilarInput('A','ab');}function right(){global $trace;$trace.='r';return new SimilarInput('B','ba');}$n=similar_text(left(),right());return $trace.':'.$n;"#;assert_eq!(run(s),Value::String("lrAB:2".into()));}
#[test]fn actual_first_conversion_throw_precedes_second_conversion(){let s=r#"$trace='';class SimilarFail{function __toString(){global $trace;$trace.='A';throw new Exception('sim-stop');}}class SimilarLater{function __toString(){global $trace;$trace.='B';return 'abc';}}try{similar_text(new SimilarFail(),new SimilarLater());return 'wrong';}catch(Exception $e){return $trace.':'.$e->getMessage();}"#;assert_eq!(run(s),Value::String("A:sim-stop".into()));}
#[test]fn actual_percent_alias_and_existing_argument_reevaluation(){assert_eq!(run("function similar_alias($a,$b){similar_text($a,$b,$a);return $a;}return similar_alias('ab','ba');"),Value::F64(100.));let s=r#"$trace='';function left(){global $trace;$trace.='l';return 'ab';}function right(){global $trace;$trace.='r';return 'ba';}function traced(){global $trace;similar_text(left(),right(),$percent);return $trace.':'.$percent;}return traced();"#;assert_eq!(run(s),Value::String("lrlr:100".into()),"retain supported standalone walker duplicated evaluation, not PHP parity");}
#[test]#[ignore="Existing assigned three-argument call bypasses percentage lowering; independent normative gap, not this optimization"]fn normative_assigned_percent_alias_gap(){assert_eq!(run("$a='ab';$b='ba';$n=similar_text($a,$b,$a);return $n.':'.$a;"),Value::String("2:100".into()));}

#[test]fn actual_unicode_bitmap_threshold_and_surrogate_policies() {
 for (a,b) in [("α".repeat(127),"β".repeat(129)),("α".repeat(128),"β".repeat(128)),
               ("α".repeat(128),"α".repeat(128)),("α".repeat(256),"αβ".repeat(128)),
               ("😀".repeat(128),"🦀".repeat(128)),("\u{ffff}".repeat(128),"\u{ffff}".repeat(128))] {
  let units=|s:&str|s.encode_utf16().map(|u|if (0xd800..=0xdfff).contains(&u){0xfffd}else{u}).collect::<Vec<_>>();
  let seen=units(&a);let expected=units(&b).iter().filter(|u|seen.contains(u)).count();
  assert_eq!(run(&format!("return similar_text('{a}','{b}');")),Value::F64(expected as f64));
 }
}
